<script setup lang="ts">
import {instrumentLabel,instrumentName} from '../utils/instrumentNames'
import {computed,onMounted,onUnmounted,ref,watch} from 'vue'
import {Activity,BellRing,Plus,RefreshCw} from 'lucide-vue-next'
import {monitoringApi,type MonitorAsset,type MonitorCatalog,type MonitorJob,type MonitorEvent,type MonitorParameters} from '../services/monitoring'
import {hasPermission} from '../services/auth'
import {formatTime} from '../utils/format'
const props=withDefaults(defineProps<{assetType:MonitorAsset;symbol:string;paused?:boolean}>(),{paused:false})
const catalog=ref<MonitorCatalog|null>(null),jobs=ref<MonitorJob[]>([]),events=ref<MonitorEvent[]>([])
const loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),query=ref(''),eventQuery=ref(''),jobPage=ref(1),eventPage=ref(1),jobTotal=ref(0),eventTotal=ref(0),monitorFilter=ref(''),unread=ref(false)
const editor=ref<{id?:string;name:string;symbol:string;enabled:boolean;seconds:number;version:number;parameters:MonitorParameters}|null>(null)
const confirmation=ref<{title:string;detail:string;action:()=>Promise<unknown>}|null>(null),detail=ref<MonitorEvent|null>(null)
const resource=computed(()=>props.assetType==='OPTION'?'options':'market'),canWrite=computed(()=>hasPermission(resource.value+'.write'))
const kindLabel=computed(()=>props.assetType==='OPTION'?'期权':'期货')
const states:Record<string,string>={STARTING:'等待检查',WARMING:'窗口预热',READY:'运行中',STALE:'行情过时 / 休市',ERROR:'等待重试',FORBIDDEN:'权限暂停',PAUSED:'已暂停',EXPIRED:'已到期'}
let alive=true,version=0,timer:number|undefined
const clone=<T,>(v:T):T=>JSON.parse(JSON.stringify(v)) as T
async function load(){
 if(loading.value)return;loading.value=true;const ticket=++version,kind=props.assetType;error.value=''
 try{const results=await Promise.all([monitoringApi.jobs(kind,query.value,jobPage.value),monitoringApi.events(kind,eventQuery.value,eventPage.value,monitorFilter.value,unread.value)]);if(!alive||ticket!==version)return;jobs.value=results[0].items;jobTotal.value=results[0].total;events.value=results[1].items;eventTotal.value=results[1].total}
 catch(e){if(alive&&ticket===version)error.value=e instanceof Error?e.message:'后台监控读取失败。'}finally{if(alive&&ticket===version)loading.value=false}
}
async function initialize(){try{catalog.value=await monitoringApi.catalog(props.assetType);if(alive)await load()}catch(e){if(alive)error.value=e instanceof Error?e.message:'监控服务暂不可用。'}}
function edit(job?:MonitorJob){if(!catalog.value)return;const parameters=clone(job?.parameters??catalog.value.defaults);if(!job&&props.assetType==='OPTION')parameters.bigLots=20;editor.value={id:job?.id,name:job?.name??`${instrumentName(props.symbol)}监控`,symbol:job?.symbol??props.symbol,enabled:job?.enabled??true,seconds:job?.seconds??60,version:job?.version??0,parameters};error.value='';confirmation.value=null}
async function save(){if(!editor.value||busy.value)return;busy.value=true;error.value='';try{await monitoringApi.save(props.assetType,editor.value,editor.value.id);editor.value=null;notice.value='监控已保存，由服务器持续运行。首次检查建立基线，不补发历史触发。';await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败。'}finally{busy.value=false}}
async function confirm(){if(!confirmation.value||busy.value)return;busy.value=true;error.value='';try{await confirmation.value.action();confirmation.value=null;notice.value='操作已保存。';await load()}catch(e){error.value=e instanceof Error?e.message:'操作失败。'}finally{busy.value=false}}
function toggle(job:MonitorJob){confirmation.value={title:job.enabled?'暂停后台监控':'恢复后台监控',detail:`${instrumentLabel(job.symbol)} · ${job.name}。${job.enabled?'暂停后不再产生新触发记录。':'恢复时重新建立基线，不补发历史触发。'}`,action:()=>monitoringApi.enabled(props.assetType,job,!job.enabled)}}
function archive(job:MonitorJob){confirmation.value={title:'归档监控任务',detail:`将停止并归档 ${job.name}，已有触发记录保留。`,action:()=>monitoringApi.archive(props.assetType,job)}}
async function ack(event:MonitorEvent){if(busy.value)return;busy.value=true;try{await monitoringApi.acknowledge(props.assetType,event.id);await load()}catch(e){error.value=e instanceof Error?e.message:'标记失败。'}finally{busy.value=false}}
async function searchJobs(){jobPage.value=1;await load()}
async function searchEvents(){eventPage.value=1;await load()}
async function pageEvents(delta:number){eventPage.value+=delta;await load()}
async function pageJobs(delta:number){jobPage.value+=delta;await load()}
watch(()=>props.assetType,()=>{++version;loading.value=false;catalog.value=null;jobs.value=[];events.value=[];editor.value=null;void initialize()})
watch(()=>props.paused,value=>{if(!value)void load()})
onMounted(()=>{void initialize();timer=window.setInterval(()=>{if(!document.hidden&&!props.paused&&!busy.value&&!editor.value&&!confirmation.value)void load()},5000)})
onUnmounted(()=>{alive=false;++version;window.clearInterval(timer)})
</script>
<template>
 <section class="monitor-panel" :aria-label="`${kindLabel}后台监控`">
  <header class="monitor-heading"><div><p class="eyebrow">SERVER MONITOR / {{kindLabel}}</p><h3><Activity :size="17"/>后台持续监控</h3><p>当前租户共享 · 关闭页面仍运行 · 按最后保存者的当前权限执行</p></div><div class="actions"><button :disabled="loading||busy" @click="load"><RefreshCw :size="14"/>刷新</button><button v-if="canWrite" class="primary" :disabled="!catalog||!symbol||busy" @click="edit()"><Plus :size="14"/>监控当前{{kindLabel}}合约</button></div></header>
  <p v-if="paused" class="monitor-note">页面刷新已暂停；服务器监控仍继续。停止任务请使用下方“暂停”。</p>
  <p v-if="notice" class="monitor-notice" role="status">{{notice}}</p><p v-if="error" class="monitor-error" role="alert">{{error}} <button @click="initialize">重试</button></p>
  <div v-if="confirmation" class="monitor-confirm" role="alertdialog" :aria-label="confirmation.title"><strong>{{confirmation.title}}</strong><p>{{confirmation.detail}}</p><button :disabled="busy" @click="confirmation=null">取消</button><button :disabled="busy" @click="confirm">确认操作</button></div>
  <form v-if="editor" class="monitor-editor" aria-label="监控规则配置" @submit.prevent="save"><fieldset :disabled="busy"><div class="editor-grid"><label>任务名称<input v-model="editor.name" required maxlength="80" aria-label="监控任务名称"/></label><label>绑定合约<input :value="instrumentLabel(editor.symbol)" readonly aria-label="监控绑定合约"/></label><label>技术指标周期<select v-model.number="editor.seconds" aria-label="监控 K 线周期"><option v-for="s in catalog?.frequencies??[]" :key="s" :value="s">{{s/60}} 分钟</option></select></label><label>60 秒涨跌阈值 / %<input v-model.number="editor.parameters.jumpPct" type="number" min="0.1" max="1000" step="0.1" required aria-label="60 秒涨跌阈值"/></label><label>大额成交增量 / 手<input v-model.number="editor.parameters.bigLots" type="number" min="1" max="1000000" step="1" required aria-label="大额成交手数"/></label><label>放量倍数<input v-model.number="editor.parameters.volumeMultiple" type="number" min="1" max="100" step="0.1" required aria-label="放量倍数"/></label><label>通道／量能回看根数<input v-model.number="editor.parameters.lookback" type="number" min="5" max="120" step="1" required/></label><label>布林标准差倍数<input v-model.number="editor.parameters.bollStd" type="number" min="0.5" max="10" step="0.1" required/></label><label>ATR 倍数<input v-model.number="editor.parameters.atrMultiple" type="number" min="0.5" max="20" step="0.1" required/></label><label>技术／涨跌提示冷却 / 秒<input v-model.number="editor.parameters.cooldownSeconds" type="number" min="10" max="3600" step="1" required/></label><label>背离枢轴右侧确认根数<input v-model.number="editor.parameters.pivotBars" type="number" min="1" max="5" step="1" required/></label><label class="inline"><input v-model="editor.enabled" type="checkbox"/>保存后启用</label></div><div class="ma-picks"><span>均线突破：</span><label v-for="ma in [5,10,20,60,180]" :key="ma" class="inline"><input v-model="editor.parameters.maPeriods" type="checkbox" :value="ma"/>MA{{ma}}</label></div><details open class="rule-picks"><summary>监控条件（{{editor.parameters.rules.length}} 项）</summary><div><label v-for="rule in catalog?.rules??[]" :key="rule.code" class="inline"><input v-model="editor.parameters.rules" type="checkbox" :value="rule.code"/>{{rule.label}}</label></div></details><p class="monitor-note">主连保存时绑定到主源确认的实际交割合约，不自动换月。放量突破按上一组完整 K 线判断；MACD 为 12/26/9，背离在后续 K 线确认后记录。大额成交按 Tick 增量手数及估算方向判断，不代表逐笔委托或主力身份。</p><div class="actions"><button type="button" @click="editor=null">取消</button><button class="primary" :disabled="!editor.parameters.rules.length">{{busy?'正在保存…':'保存后台监控'}}</button></div></fieldset></form>
  <form class="monitor-toolbar" @submit.prevent="searchJobs"><input v-model="query" placeholder="搜索任务名称或合约" aria-label="搜索监控任务"/><button :disabled="loading||busy">查询任务</button><span>{{jobTotal}} 个任务 · 每租户最多 {{catalog?.maxEnabledPerTenant??20}} 个启用</span></form>
  <div class="monitor-table"><table><thead><tr><th>任务 / 绑定合约</th><th>运行状态</th><th>最近检查 / 行情时点</th><th>操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id"><td><strong>{{job.name}}</strong><small>{{instrumentLabel(job.symbol)}} · {{job.seconds/60}} 分钟 · {{job.parameters.rules.length}} 条规则</small></td><td><span :class="['status',job.status.toLowerCase()]">{{states[job.status]??job.status}}</span><small>{{job.message}}</small><small v-if="job.enabled&&job.checkedAt&&Date.now()-Date.parse(job.checkedAt)>30000">检查心跳已超过 30 秒，请检查后台服务。</small></td><td><time>{{formatTime(job.checkedAt)}}</time><small>行情 {{formatTime(job.sourceTimestamp)}}</small></td><td class="row-actions"><button v-if="canWrite" :disabled="busy" @click="edit(job)">编辑规则</button><button v-if="canWrite" :disabled="busy" @click="toggle(job)">{{job.enabled?'暂停':'恢复'}}</button><button v-if="canWrite" :disabled="busy" @click="archive(job)">归档</button></td></tr></tbody></table><p v-if="!jobs.length" class="empty">{{loading?'正在读取后台任务…':'还没有后台监控；可为当前合约创建任务。'}}</p></div>
  <div v-if="jobTotal>20" class="monitor-pagination"><span>任务第 {{jobPage}} 页</span><button :disabled="jobPage<=1||loading" @click="pageJobs(-1)">上一页</button><button :disabled="jobPage*20>=jobTotal||loading" @click="pageJobs(1)">下一页</button></div>
  <header class="events-heading"><h4><BellRing :size="16"/>已保存的触发记录</h4><span>{{eventTotal}} 条 · 首次建立基线不补历史提醒</span></header><form class="monitor-toolbar" @submit.prevent="searchEvents"><input v-model="eventQuery" placeholder="合约 / 信号 / 规则编码" aria-label="搜索监控触发"/><select v-model="monitorFilter" aria-label="触发任务筛选"><option value="">全部任务</option><option v-for="job in jobs" :key="job.id" :value="job.id">{{job.name}}</option></select><label class="inline"><input v-model="unread" type="checkbox"/>仅未读</label><button :disabled="loading||busy">查询记录</button></form>
  <div class="monitor-table"><table><thead><tr><th>确认行情时点</th><th>合约</th><th>触发条件</th><th>记录时间</th><th>操作</th></tr></thead><tbody><tr v-for="event in events" :key="event.id"><td>{{formatTime(event.observedAt)}}</td><td class="mono">{{instrumentLabel(event.symbol)}}</td><td><strong>{{event.label}}</strong><small>{{event.rule}}</small></td><td>{{formatTime(event.createdAt)}}</td><td class="row-actions"><button @click="detail=event">触发依据</button><button v-if="canWrite&&!event.acknowledgedAt" :disabled="busy" @click="ack(event)">标记已读</button><span v-else-if="event.acknowledgedAt">已读</span></td></tr></tbody></table><p v-if="!events.length" class="empty">没有触发记录。休市、过时、历史不足和窗口预热均不会补造信号。</p></div>
  <div class="monitor-pagination"><span>触发记录第 {{eventPage}} 页</span><button :disabled="eventPage<=1||loading" @click="pageEvents(-1)">上一页</button><button :disabled="eventPage*20>=eventTotal||loading" @click="pageEvents(1)">下一页</button></div>
  <section v-if="detail" class="event-detail" aria-label="监控触发依据"><header><h4>{{instrumentLabel(detail.symbol)}} · {{detail.label}}</h4><button @click="detail=null">关闭详情</button></header><p>确认行情时点 {{formatTime(detail.observedAt)}} · 保存 {{formatTime(detail.createdAt)}} · {{detail.algorithmVersion}}</p><pre>{{JSON.stringify(detail.evidence,null,2)}}</pre></section>
 </section>
</template>
<style scoped>
.monitor-panel{color:#dce6ed;background:#182430;border:1px solid #2a3a49;border-radius:8px;min-width:0;overflow:hidden}.monitor-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem;flex-wrap:wrap;padding:1.2rem}.eyebrow{font:.58rem var(--font-numeric);letter-spacing:.1em;color:#96b9cd;margin:0}.monitor-heading h3,.events-heading h4{display:flex;gap:.5rem;align-items:center;font-size:.9rem;font-weight:500;margin:.65rem 0}.monitor-heading p:last-child{color:#94a5b6;font-size:.62rem;line-height:1.8;margin:0}.actions,.row-actions,.monitor-toolbar,.monitor-pagination{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap}button{display:inline-flex;gap:.35rem;align-items:center;justify-content:center;cursor:pointer;font:.65rem var(--font-sans);padding:.5rem .65rem;color:#dce6ed;background:#203140;border:1px solid #3a5061;border-radius:4px}button.primary{background:#305570}button:disabled{opacity:.45;cursor:default}input,select{color:#dce6ed;background:#101d28;border:1px solid #354b5d;border-radius:4px;padding:.6rem;font:.68rem var(--font-sans);min-width:0}input[type=checkbox]{accent-color:#8cbed9;width:14px;height:14px;margin:0}.monitor-note,.monitor-notice,.monitor-error{font-size:.63rem;line-height:1.9;padding:.7rem 1.2rem;margin:0}.monitor-note{color:#94a5b6}.monitor-notice{color:#94d6bb;background:#183d362e}.monitor-error{color:#e3c390;background:#4d3b2240}.monitor-error button{padding:.2rem .4rem;margin-left:.5rem}.monitor-toolbar{padding:.8rem 1.2rem;background:#14212c;border-block:1px solid #2a3a49}.monitor-toolbar>input{flex:1;min-width:9rem}.monitor-toolbar>span{color:#94a5b6;font-size:.58rem}.inline{display:flex;align-items:center;gap:.4rem;font-size:.63rem;color:#b6c6d1}.monitor-table{overflow:auto;max-width:100%}table{width:100%;border-collapse:collapse;text-align:left;font-size:.65rem}th,td{padding:.85rem 1rem;border-bottom:1px solid #2a3a49;vertical-align:top}th{font-size:.6rem;color:#94a5b6;font-weight:400;white-space:nowrap}td strong{font-weight:500;font-size:.68rem}td small{display:block;font-size:.58rem;color:#94a5b6;line-height:1.8;max-width:26rem;margin-top:.35rem}td time,.mono{font-family:var(--font-numeric)}.row-actions{white-space:nowrap;min-width:10rem}.row-actions button{padding:.25rem .4rem;font-size:.58rem}.row-actions>span{color:#94a5b6;font-size:.6rem}.status{font-size:.62rem;color:#cfbb8e}.status.ready{color:#76d3b1}.status.forbidden,.status.error{color:#ed9d93}.empty{padding:1.7rem 1rem;text-align:center;font-size:.65rem;color:#94a5b6;line-height:1.8}.events-heading{display:flex;align-items:center;justify-content:space-between;gap:1rem;padding:.6rem 1.2rem}.events-heading>span,.monitor-pagination span{color:#94a5b6;font-size:.58rem}.monitor-pagination{padding:.8rem 1.2rem;justify-content:end}.monitor-pagination span{margin-right:auto}.monitor-editor{padding:1rem 1.2rem;background:#14212c;border-block:1px solid #466175}.monitor-editor fieldset{margin:0;padding:0;border:0;min-width:0}.editor-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.8rem}.editor-grid label{display:grid;gap:.4rem;font-size:.62rem;color:#a7bac8}.editor-grid label.inline{display:flex;align-items:center}.ma-picks{display:flex;flex-wrap:wrap;align-items:center;gap:.8rem;padding:1rem 0;font-size:.63rem;color:#94a5b6}.rule-picks{border:1px solid #354b5d;border-radius:4px;padding:.8rem}.rule-picks summary{font-size:.67rem;cursor:pointer}.rule-picks>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.8rem;padding-top:1rem}.monitor-confirm{padding:1rem 1.2rem;background:#51402240;border-block:1px solid #796139;font-size:.72rem}.monitor-confirm p{font-size:.65rem;line-height:1.8;color:#c1b498}.monitor-confirm button{margin-right:.5rem}.event-detail{margin:1rem;border:1px solid #466175;border-radius:5px;padding:1rem;min-width:0}.event-detail header{display:flex;align-items:center;justify-content:space-between;gap:1rem}.event-detail h4{font-size:.75rem;margin:0}.event-detail p{font-size:.62rem;line-height:1.8;color:#94a5b6}.event-detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font:.63rem/1.8 var(--font-numeric);max-height:25rem;overflow:auto;background:#101d28;padding:1rem}.event-detail button{font-size:.6rem}@media(max-width:900px){.editor-grid,.rule-picks>div{grid-template-columns:repeat(2,minmax(0,1fr))}.events-heading{flex-wrap:wrap}}@media(max-width:520px){.monitor-heading,.monitor-toolbar,.events-heading{padding:1rem .8rem}.editor-grid,.rule-picks>div{grid-template-columns:minmax(0,1fr)}.monitor-editor{padding:1rem .8rem}.monitor-toolbar>input{flex-basis:100%}.monitor-toolbar select{max-width:100%}.event-detail header{align-items:start}.event-detail h4{line-height:1.7}.monitor-note,.monitor-error,.monitor-notice{padding:.7rem .8rem}}
</style>
